const item = $json;

if (!item.event_id || !item.lease_token || !item.job_id) {
  throw new Error("Missing claimed failure event ownership");
}

const safe = (value, max = 180) =>
  String(value ?? "")
    .replace(/[`*_~<>@]/g, "")
    .replace(/https?:\/\/\S+/gi, "[URL redacted]")
    .replace(/[\r\n\t]/g, " ")
    .slice(0, max);

const message = [
  "🚨 DOCUMENT INDEXING FAILURE",
  "",
  `Document: ${safe(item.filename, 120)}`,
  `Job ID: ${item.job_id}`,
  `Document ID: ${item.document_id}`,
  `Organization ID: ${item.organization_id}`,
  `Error: ${safe(item.error_message, 300)}`,
  `Occurred at: ${item.occurred_at}`,
  "",
  "Action required: Investigate the indexing job in IncidentIQ.",
  "Do not automatically retry until the failure is reviewed."
].join("\n");

return {
  json: {
    event_id: item.event_id,
    lease_token: item.lease_token,
    discord_message: message
  }
};

